def split_university_and_country(apps, schema_editor):
    ExchangeProgram = apps.get_model('faculty', 'ExchangeProgram')
    for program in ExchangeProgram.objects.all():
        text = program.university

        # Розбираємо різні формати запису деканату
        if '(' in text and ')' in text:
            parts = text.split('(')
            parts[1] = parts[1].replace(')', '')
        elif '-' in text:
            parts = text.split('-')
        elif ',' in text:
            parts = text.split(',')
        else:
            parts = [text, '']

        program.university = parts[0].strip()
        if len(parts) > 1:
            program.country = parts[1].strip()

        program.save()


def reverse_split(apps, schema_editor):
    ExchangeProgram = apps.get_model('faculty', 'ExchangeProgram')
    for program in ExchangeProgram.objects.all():
        if program.country:
            program.university = f"{program.university}, {program.country}"
            program.country = ""
        program.save()


